INSERT INTO public.news (category, title_en, title_ar, body_en, body_ar, pinned, published_at)
VALUES (
  'update',
  'Final Polish Update',
  'تحديث اللمسات الأخيرة',
  'Card backs now keep their exact artwork with no cropping, and the flip looks like one physical card. New in Settings → Animations: Flip Card Reveal (on by default) and Haptics. Every rarity has its own cinematic reveal sound — Mythic is the loudest of all. Cards now glow with an animated rarity aura, load faster with preloaded art, and five new fighters joined the roster: Isshin (92), Masaki (92), Zangetsu (95), Äs Nödt (88) and Gremmy (90).',
  'أصبحت ظهور البطاقات تحافظ على شكلها الأصلي بلا اقتصاص، والقلب يبدو كبطاقة واحدة حقيقية. جديد في الإعدادات ← الحركات: كشف البطاقة بالقلب (مفعّل افتراضياً) والاهتزاز. لكل ندرة صوت كشف خاص بها، والخرافي هو الأكثر إبهاراً. البطاقات الآن بهالة متحركة حسب الندرة وتحميل أسرع، وانضم خمسة مقاتلين جدد: إيسشين (92)، ماساكي (92)، زانغيتسو (95)، آس نودت (88)، غريمي (90).',
  true,
